"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[90128],{28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>h});var a=n(96540);const o={},i=a.createContext(o);function s(e){const t=a.useContext(i);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:t},e.children)}},45107:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>h,default:()=>m,frontMatter:()=>s,metadata:()=>a,toc:()=>u});const a=JSON.parse('{"id":"tangfen/whyhumanthoughtislimited","title":"","description":"In mathematics, for things that are hard to calculate, we don\'t need to calculate them directly, because mathematics has inequalities. For example, to prove that \\"human thoughts\\" and \\"human ideas\\" are finite, we don\'t need to know how many \\"human thoughts\\" or \\"human ideas\\" there are. We only need to find something that exceeds \\"human thoughts\\" or \\"human ideas\\" in quantity, and if that thing is finite, then \\"human thoughts\\" and \\"human ideas\\" are finite. This is the simplest mathematical problem. If you still have doubts about this, then I can only advise you not to discuss this topic anymore -- go back and review elementary school math first.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/whyhumanthoughtislimited.md","sourceDirName":"tangfen","slug":"/tangfen/whyhumanthoughtislimited","permalink":"/tangfen/whyhumanthoughtislimited","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"whyhumanthoughtislimited","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"\u4e3a\u4e86\u8bba\u575b\u7684\u4e25\u8083\u6027\uff0c\u8bf7\u5403\u4eba\u5bb6\u5634\u77ed\u3001\u6cd5\u5170\u897f\u5927\u83dc\u5e08\u5085\u7b49\u4eba\u4e0d\u8981\u4efb\u610f\u7f16\u9020\uff01","permalink":"/tangfen/stopfaking"},"next":{"title":"ZT:\u4e2d\u8bd1\u672c\u300a\u8d44\u672c\u8bba\u300b\u4e2d\u5173\u4e8e\u52b3\u52a8\u4ef7\u503c\u7406\u8bba\u4e00\u6bb5\u6587\u5b57\u8bef\u8bd1\u7684\u95ee\u9898\uff08\u6ce8\uff1a\u7f20\u8f6c\u8d34\uff09","permalink":"/tangfen/someproblemofcaptical"}}');var o=n(74848),i=n(28453);const s={id:"whyhumanthoughtislimited",title:"",hide_table_of_contents:!0},h='For the Last Time, Using a Main Post to Tell You Why "Human Thoughts" and "Human Ideas" Are Finite!',r={},u=[];function l(e){const t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"for-the-last-time-using-a-main-post-to-tell-you-why-human-thoughts-and-human-ideas-are-finite",children:'For the Last Time, Using a Main Post to Tell You Why "Human Thoughts" and "Human Ideas" Are Finite!'})}),"\n",(0,o.jsx)(t.p,{children:'In mathematics, for things that are hard to calculate, we don\'t need to calculate them directly, because mathematics has inequalities. For example, to prove that "human thoughts" and "human ideas" are finite, we don\'t need to know how many "human thoughts" or "human ideas" there are. We only need to find something that exceeds "human thoughts" or "human ideas" in quantity, and if that thing is finite, then "human thoughts" and "human ideas" are finite. This is the simplest mathematical problem. If you still have doubts about this, then I can only advise you not to discuss this topic anymore -- go back and review elementary school math first.'}),"\n",(0,o.jsx)(t.p,{children:"From modern physics, we know the existence time of the universe is finite. Therefore the total number of humans that can ultimately exist in the universe is also finite. The reasoning is simple. As for whether humanity can survive until the universe perishes -- that's actually not important, and my guess is we won't get that chance. Since the total number of humans is finite, we only need to prove that each person's thoughts, ideas, and such are finite to prove the total number of all human thoughts is finite. This too is the simplest elementary school math. If anyone still needs an explanation, my answer is the same: please go back to elementary school. We know every person must die, meaning human life is finite. So to prove each person's thoughts, ideas, etc. are finite, we only need to prove that the interval at which each person produces thoughts and ideas cannot be infinitely short. This again is the simplest elementary school math. If anyone still needs an explanation, same answer: please go back to elementary school."}),"\n",(0,o.jsx)(t.p,{children:"So can the interval at which each person produces thoughts and ideas be infinitely short? Obviously not, because each person's thought- and idea-producing interval cannot be shorter than the minimum response time of brain neurons to stimulation. The reason is that human thoughts and ideas depend on the brain's physiological foundation. If anyone doubts this, then you must find a person without a brain who can still think. Until such a person is found, the materialist foundation that human thoughts and ideas depend on the brain's physiological basis will not be shaken."}),"\n",(0,o.jsx)(t.p,{children:"Research on the human brain long ago told us that the minimum response time of any brain neuron to stimulation is not infinitely short. Therefore the interval at which each person produces thoughts and ideas is also not infinitely short. Here, we don't need to know how many ideas we have in a certain period of time -- we only need to know that the time interval for producing an idea is not infinitely short. This again is the simplest elementary school math. If anyone still needs an explanation, same answer: please go back to elementary school."}),"\n",(0,o.jsx)(t.p,{children:"From the above analysis we know that the quantity of all human thoughts and ideas is finite. Of course, we don't know the exact number, but we can demonstrate its finiteness. No matter how large the number is, it's still finite. The above analysis should be understandable to anyone at an elementary school level. The only possible difficulty might be \"each person's thought- and idea-producing interval cannot be shorter than the minimum response time of brain neurons to stimulation.\" If you find this doubtful -- meaning you think you're special, different from ordinary people, that you produce thoughts faster than the minimum response time of brain neurons, or that the neurons in your brain can respond to stimulation infinitely fast -- then I think you don't need to continue in these debates. What you should do instead is two things: First, remove all the neurons from your brain, then demonstrate to the whole world whether one can still think without brain neurons. Second, or donate your neurons to the relevant national laboratory to test whether their response speed is infinitely fast. If the experiment succeeds, a Nobel Prize is probably inescapable. Since everyone here is patriotic, and you believe your brain cells are naturally special, you might as well make a contribution to China's scientific enterprise."}),"\n",(0,o.jsx)(t.p,{children:"I truly hope your experiment succeeds. As for how to remove all your brain neurons or how to contact the relevant institution to donate your infinitely fast-responding neurons -- there are many methods for that. There's no need to discuss them here."})]})}function m(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}}}]);